import{_ as t}from"./chunks/test-case-detail.C5uQxYLf.js";import{_ as a,o,c as r,ak as s}from"./chunks/framework.sV-XtlWr.js";const f=JSON.parse('{"title":"Failure evidence","description":"","frontmatter":{"title":"Failure evidence","lang":"en-US"},"headers":[],"relativePath":"evidence.md","filePath":"evidence.md","lastUpdated":1785722971000}'),n={name:"evidence.md"};function i(d,e,c,h,l,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="failure-evidence" tabindex="-1">Failure evidence <a class="header-anchor" href="#failure-evidence" aria-label="Permalink to &quot;Failure evidence&quot;">​</a></h1><p>When a test fails, everything Piwi captured about that attempt lands on one screen. This page describes that screen — what each block holds, where the data came from, and how much more you get once a trace is attached.</p><p>Two different pages are involved, and <a href="./concepts.html#execution">Core concepts</a> draws the line between them:</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>Answers</th></tr></thead><tbody><tr><td><strong>Execution</strong></td><td><code>/test-run-cases/:id</code></td><td>&quot;why did this attempt fail?&quot; — <a href="#one-execution-diagnosis-first">the diagnosis view</a></td></tr><tr><td><strong>Test case</strong></td><td><code>/test-cases/:id</code></td><td>&quot;how has this test behaved over time?&quot; — <a href="#the-test-case-page">its history</a></td></tr></tbody></table><p>Most links from a run land on an execution; the test&#39;s title links to the test case above it.</p><h2 id="one-execution-diagnosis-first" tabindex="-1">One execution, diagnosis-first <a class="header-anchor" href="#one-execution-diagnosis-first" aria-label="Permalink to &quot;One execution, diagnosis-first&quot;">​</a></h2><p>Everything about a single test execution, laid out <strong>diagnosis-first</strong>. A pinned <strong>summary</strong> carries the status, title, copyable location, duration, worker, retries and duration-vs-average, plus at-a-glance <strong>signal badges</strong> (new regression, new flaky, passed-on-retry), any test annotations (<code>@fixme</code>, <code>@slow</code>, …), the <strong>wasted time</strong> spent in fixed waits, and metadata cards (environment, CI, branch, commit, author, browser, storage). Traces stream in live while the parent run is still running.</p><p>The tabs adapt to the result.</p><p><strong>A failing execution opens on the Diagnosis tab</strong> — the whole investigation on one screen, modeled on the <a href="./ui-overview.html#failure-cluster-detail">failure cluster</a> page you already know. It leads with the raw <strong>error</strong> (copyable), then splits into a right-hand rail and a left-hand evidence funnel:</p><ul><li><strong>Verdict</strong> — is this a new regression or flaky, how many times it retried, and how long the test has been failing, with a clickable recent-runs strip to jump between executions.</li><li><strong>Failure cluster</strong> <em>(when the failure is clustered)</em> — signature, error type, how many tests it hit, the cluster&#39;s own AI verdict, and a hand-off to the full cross-test investigation.</li><li><strong>AI diagnosis</strong> — diagnose <em>this execution</em> with one click, or <strong>Copy AI context</strong> to paste the full evidence bundle into your own assistant (works even with no provider configured). Cited evidence links jump to the matching section on the page.</li><li><strong>Evidence funnel</strong> — the <strong>test source</strong> as a call stack (the line that actually threw plus the callers above it, so a failure inside a helper is visible, not just the test line that invoked it — and, <a href="#trace-powered-deep-views">with a trace</a>, the complete stack with real source), grouped <strong>failure evidence</strong> (screenshots, video, traces, attachments), <a href="./reporter.html#locator-healing">alternative locators</a> for a broken locator, an <strong>environment diff</strong> and <strong>visual diff</strong> against the last green run, <strong>console</strong> output, <strong>network requests</strong> with inline <a href="./backend-logs.html">backend logs</a> and a <a href="#trace-powered-deep-views">Full trace</a> network view, <strong>app state</strong>, the failure-time <strong>ARIA snapshot</strong>, and the reconstructed <strong>DOM snapshot</strong>.</li></ul><p><strong>A passing execution opens on Steps</strong>, with an <strong>Artifacts</strong> tab for its traces, attachments, console and network.</p><p>Both keep a <strong>Performance</strong> tab (performance hints plus color-coded <strong>Web Vitals</strong>) and a <strong>History</strong> tab (this test&#39;s status and duration trend over recent runs, linking through to the full test history). A <strong>Copy retry command</strong> button in the header gives you the exact Playwright command to re-run just this test. The Web Vitals, network, console, ARIA-snapshot and alternative-locator data all come from the <a href="./capture-fixtures.html">capture fixtures</a>.</p><h2 id="trace-powered-deep-views" tabindex="-1">Trace-powered deep views <a class="header-anchor" href="#trace-powered-deep-views" aria-label="Permalink to &quot;Trace-powered deep views&quot;">​</a></h2><p>When an execution has an uploaded trace, two evidence blocks go deeper — no configuration beyond recording traces (<code>trace: &#39;retain-on-failure&#39;</code> or <code>&#39;on-first-retry&#39;</code> in your Playwright config):</p><ul><li><strong>Test source → Full stack</strong> — the complete call stack of the failing action from the trace&#39;s stacks index, every frame with its real source read from the trace&#39;s embedded files (recorded by default with the Playwright test runner), the failing line highlighted, dependency frames folded, and Open-in-IDE links on each in-project frame. A toggle switches back to the reporter-captured frames.</li><li><strong>Network → Full trace</strong> — every request the page made (documents, scripts, images — not just fetch/XHR), on a waterfall with the failing action&#39;s time window shaded. Click a request for timing phases, request/response headers, and a capped body preview (JSON pretty-printed, images inline). Sensitive header values (<code>Authorization</code>, <code>Cookie</code>, …) are masked server-side and never leave the dashboard, and token-shaped strings in URLs and bodies are masked too.</li></ul><p>Executions without a trace keep the reporter-captured baseline — the blocks simply hint at what a trace would add. Traces recorded without embedded sources still show the full frame list.</p><h2 id="trace-viewer" tabindex="-1">Trace viewer <a class="header-anchor" href="#trace-viewer" aria-label="Permalink to &quot;Trace viewer&quot;">​</a></h2><p>Every trace shows a <strong>View trace</strong> button that opens the full Playwright trace viewer — the same UI as <code>npx playwright show-trace</code>, with the DOM snapshot timeline, action log, network, console, and source.</p><p>The viewer is <strong>served by the dashboard itself</strong> (the <code>playwright-core</code> viewer assets are bundled and served at <code>/trace-viewer/</code>), so traces are never uploaded to a third party — unlike sending a colleague to <code>trace.playwright.dev</code>, the bytes stay on your server. Traces are stored efficiently: each archive is split into a slim events ZIP plus a project-wide, hash-deduplicated resource pool, and reconstructed on download (see <a href="./storage.html">Storage</a>). Trace blobs are content-addressed, so the browser caches them and re-opening a trace is instant.</p><div class="tip custom-block"><p class="custom-block-title">Authentication caveat</p><p>The bundled <code>/trace-viewer/</code> is same-origin, so it works whether or not <a href="./authentication.html">authentication</a> is enabled. The hosted <code>trace.playwright.dev</code> viewer is a different origin and cannot send your session cookie, so it only works against a dashboard with auth disabled — use the built-in <strong>View trace</strong> button, which always works.</p></div><h2 id="the-test-case-page" tabindex="-1">The test case page <a class="header-anchor" href="#the-test-case-page" aria-label="Permalink to &quot;The test case page&quot;">​</a></h2><p><code>/test-cases/:id</code> is the other axis: not one attempt, but the test&#39;s whole life. Total runs, pass rate, average duration and last run across every execution, a duration trend, a status-history strip, and the list of recent executions — each linking back to the diagnosis view above.</p><figure><img src="'+t+'" alt="Test case page with total runs, pass rate, failed count, average duration, flaky count and last run, above a duration trend chart, a status history strip, and a table of recent executions"><figcaption>The test case page — the across-time view: pass rate and duration stats, a duration trend, a status-history strip, and every recent execution of this one test.</figcaption></figure><h2 id="taking-it-out-of-the-dashboard" tabindex="-1">Taking it out of the dashboard <a class="header-anchor" href="#taking-it-out-of-the-dashboard" aria-label="Permalink to &quot;Taking it out of the dashboard&quot;">​</a></h2><p>Any of this can leave the dashboard as a self-contained file — for a ticket attachment, a colleague without an account, or an archive that outlives your retention window. See <a href="./offline-export.html">Offline export</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./capture-fixtures.html">Capture fixtures</a> — the one file that produces the network, console, Web Vitals and locator evidence</li><li><a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a> — the same investigation across every test sharing a fingerprint</li><li><a href="./concepts.html#execution">Core concepts</a> — execution versus test case</li><li><a href="./recipes/broken-locator.html">Fix a broken locator</a> — this page, used for one concrete job</li></ul>',27)])])}const w=a(n,[["render",i]]);export{f as __pageData,w as default};
